package main

import "fmt"

type Inner struct{ Data string }

func (i *Inner) SafeMethod() string {
	if i == nil { return "(Inner не инициализирован!)" }
	return i.Data
}

type Outer struct {
	*Inner // Встроенный указатель
}

func main() {
	o := Outer{Inner: nil}

	// 1. Безопасный вызов благодаря проверке nil внутри SafeMethod:
	fmt.Println("Вызов на Outer:", o.SafeMethod())
}

package main

import "fmt"

type WiFiModule struct{}
func (WiFiModule) Connect() { fmt.Println("📶 Wi-Fi 6 подключен (5 GHz)") }

type BluetoothModule struct{}
func (BluetoothModule) Connect() { fmt.Println("🔵 Bluetooth 5.3 сопряжен") }

type SmartDevice struct {
	WiFiModule
	BluetoothModule
	DeviceName string
}

// Разрешение конфликта имен через собственный метод:
func (sd SmartDevice) Connect() {
	fmt.Printf("[%s] Инициализация беспроводных модулей...\n", sd.DeviceName)
	sd.WiFiModule.Connect()
	sd.BluetoothModule.Connect()
}

func main() {
	dev := SmartDevice{DeviceName: "Яндекс Станция"}
	dev.Connect()
}

package main

import (
	"errors"
	"fmt"
	"strings"
)

type QueryBuilder struct {
	fields []string
	table  string
	where  string
	limit  int
}

func NewQueryBuilder() *QueryBuilder { return &QueryBuilder{} }
func (q *QueryBuilder) Select(f ...string) *QueryBuilder { q.fields = f; return q }
func (q *QueryBuilder) From(t string) *QueryBuilder       { q.table = t; return q }
func (q *QueryBuilder) Where(w string) *QueryBuilder      { q.where = w; return q }
func (q *QueryBuilder) Limit(l int) *QueryBuilder         { q.limit = l; return q }

func (q *QueryBuilder) Build() (string, error) {
	if q.table == "" { return "", errors.New("секция FROM обязательна") }
	fields := "*"
	if len(q.fields) > 0 { fields = strings.Join(q.fields, ", ") }
	sql := fmt.Sprintf("SELECT %s FROM %s", fields, q.table)
	if q.where != "" { sql += " WHERE " + q.where }
	if q.limit > 0 { sql += fmt.Sprintf(" LIMIT %d", q.limit) }
	return sql + ";", nil
}

func main() {
	sql, _ := NewQueryBuilder().
		Select("id", "email", "status").
		From("users").
		Where("status = 'active'").
		Limit(10).
		Build()
	fmt.Println("Сгенерированный SQL:", sql)
}

