package main

import "fmt"

// Маленькие, сфокусированные интерфейсы:
type Reader interface{ Read() string }
type Writer interface{ Write(data string) }
type Closer interface{ Close() error }

// Композиция интерфейсов:
type ReadWriteCloser interface {
	Reader
	Writer
	Closer
}

type SimpleStream struct{ data string }
func (s *SimpleStream) Read() string       { return s.data }
func (s *SimpleStream) Write(d string)     { s.data = d }
func (s *SimpleStream) Close() error       { return nil }

func main() {
	var rwc ReadWriteCloser = &SimpleStream{}
	rwc.Write("Потоковые данные")
	fmt.Println("Прочитано:", rwc.Read())
}

package main

import "fmt"

type BaseCounter struct{ count int }

func (b *BaseCounter) Add(n int) { b.count += n }
func (b *BaseCounter) AddAll(nums []int) {
	for _, v := range nums {
		b.Add(v)
	}
}

type LoggingCounter struct {
	BaseCounter
}

// В Go вызов lc.AddAll() вызывает BaseCounter.AddAll,
// который вызывает BaseCounter.Add, а не LoggingCounter.Add!
// Нет неявного полиморфного перехвата -> нет хрупкости!

func main() {
	lc := &LoggingCounter{}
	lc.AddAll([]string{"1", "2"} == nil) // безопасное поведение
	lc.AddAll([]int{10, 20, 30})
	fmt.Println("Итоговый подсчет:", lc.count)
}
